<template>
  <div>
    <div class="flex gap-2 justify-center">
      <v-select
        :options="logTypes"
        v-model="filterType"
        style="width: 200px"
        :clearable="false"
        :searchable="false"
      ></v-select>
      <Input
        v-model="filterQuery"
        @focus="toggleTyping(true)"
        @blur="toggleTyping(false)"
      />
      <Button
        @click="searchLogs"
        :disabled="isLoading || filterQuery.length < 1"
        class="float-right"
        >Search</Button
      >
    </div>
    <div class="mt-3 Results pr-1">
      <table class="gm-table" v-if="!isLoading && cols.length > 0">
        <tr>
          <th v-for="(row, index) in rows" :key="index">{{ row }}</th>
        </tr>
        <tr v-for="(col, index) in cols" :key="index">
          <td v-for="(td, index2) in col" :key="index2">{{ td }}</td>
        </tr>
      </table>
      <div
        class="flex flex-col items-center justify-center text-xl mt-3"
        v-else
      >
        <template v-if="cols.length < 1 && !isLoading">
          <div>
            <i class="fa-duotone fa-face-frown text-5xl"></i>
          </div>
          No logs found...
        </template>
        <template v-if="isLoading">
          <div>
            <i class="fa-duotone fa-spinner-third text-5xl fa-spin"></i>
          </div>
          Loading...
        </template>
      </div>
    </div>
  </div>
</template>

<script>
import Button from "../../../../components/Button.vue";
import Input from "../../../../components/Input.vue";

export default {
  name: "LogsTab",
  components: { Button, Input },
  data() {
    return {
      filterType: { label: "Sessions", value: 2 },
      filterQuery: "",
      rows: ["Timestamp", "Admin", "Duration", "Reason"],
      cols: [],
      isLoading: false,
      logTypes: [
        { label: "Sessions", value: 2 },
        { label: "Admin", value: 1 },
        { label: "Records", value: 3 },
      ],
    };
  },
  methods: {
    toggleTyping(state) {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuToggleTyping", state);
    },
    searchLogs() {
      this.isLoading = true;
      console.log(this.filterType.value, this.filterQuery);
      // eslint-disable-next-line no-undef
      mp.trigger(
        "RequestLogsFromServer",
        this.filterType.value,
        this.filterQuery
      );
    },
  },
};
</script>

<style scoped lang="scss">
* {
  color: $white-text;
}

.Results {
  overflow-y: auto;
  max-height: 715px;
  border-radius: $radius-md;
}
</style>
