//Vue imports
import { createApp } from "vue";
import App from "./App.vue";
import Swal from "sweetalert2/src/sweetalert2.js";
import vSelect from "vue-select";
import "./assets/plugins/coloris/coloris";
import { VTooltip } from "floating-vue";
import iziToast from "izitoast";
import "izitoast/dist/css/iziToast.min.css";

global.Modal = Swal.mixin({
  confirmButtonText: "Confirm",
});

iziToast.settings({
  theme: "gm",
  close: false,
});

global.toast = function toast(title, message, type, timeout) {
  let options = {
    transitionIn: "fadeInLeft",
    progressBar: timeout === false ? false : true,
  };
  if (title) options.title = title;
  if (message) options.message = message;
  if (timeout) options.timeout = timeout;
  switch (type) {
    case "success":
      options.icon = "fa-duotone fa-circle-check";
      iziToast.success(options);
      break;
    case "error":
      options.icon = "fa-duotone fa-circle-x";
      iziToast.error(options);
      break;
    case "warning":
      options.icon = "fa-duotone fa-circle-exclamation";
      iziToast.warning(options);
      break;
    case "info":
      options.icon = "fa-duotone fa-circle-info";
      iziToast.info(options);
      break;
    default:
      iziToast.show(options);
  }
};

// global.Modal.fire({
//   title: "Few things before you start",
//   html: '<input class="gm-input">',
//   focusConfirm: false,
// });

global.Toast = Swal.mixin({
  toast: true,
  position: "top-end",
  showConfirmButton: false,
  timer: 3000,
  timerProgressBar: true,
  color: "#f1f1f1",
  background: "#1f1f1f",
  didOpen: (toast) => {
    toast.addEventListener("mouseenter", Swal.stopTimer);
    toast.addEventListener("mouseleave", Swal.resumeTimer);
  },
});

//Tailwind css
import "./assets/styles/tailwind.css";

//Color picker css
import "./assets/plugins/coloris/coloris.css";
import "./assets/plugins/coloris/coloris.js";

//States
import { createPinia } from "pinia";

let app = createApp(App);
app.component("v-select", vSelect);

//Tooltip
import "floating-vue/dist/style.css";
app.directive("tooltip", VTooltip, {
  themes: {
    tooltip: {
      $extend: "tooltip",
      triggers: ["hover"],
      autoHide: true,
      placement: "auto",
    },
  },
});

app.use(createPinia());

window.gm = app.mount("#app");
