<template>
  <div v-if="screenshots">
    <div class="flex gap-2 justify-center">
      <v-select
        :options="['Admin', 'Player']"
        v-model="filterType"
        style="width: 200px"
        :clearable="false"
        :searchable="false"
      ></v-select>
      <Input
        v-model="filterQuery"
        @input="showLimit = 20"
        @focus="toggleTyping(true)"
        @blur="toggleTyping(false)"
      />
      <Button @click="refreshHandler" :disabled="isLoading" class="float-right"
        >Refresh</Button
      >
    </div>
    <div class="Screenshots mt-3">
      <div class="grid gap-3 grid-cols-3" v-if="filtredScreenshots.length > 0">
        <TransitionGroup name="list">
          <ScreenshotCard
            v-for="(file, index) in filtredScreenshots.slice(0, showLimit)"
            :key="file"
            :image="`https://phpscreenshotserver.ls-cc.info/screenshots/${file.name}`"
            :admin="file.admin"
            :player="file.player"
            :data-index="index"
            :getScreenshots="getScreenshots"
            :fileName="file.name"
            :api="api"
            @click="ssClickHandler(file)"
          />
        </TransitionGroup>
      </div>
      <div
        v-if="
          filtredScreenshots.length > 20 &&
          showLimit < filtredScreenshots.length
        "
        class="w-full flex justify-center items-center h-20"
      >
        <Button @click="showLimit += 20">Load more</Button>
      </div>
    </div>
    <div
      v-if="filtredScreenshots.length <= 0"
      class="flex flex-col h-36 justify-center items-center text-2xl"
    >
      <template v-if="isLoading">
        <i class="fa-duotone fa-spinner-third fa-spin text-5xl"></i>
        Loading...
      </template>
      <template v-else>
        <i class="fa-duotone fa-face-frown-slight text-5xl"></i>
        No screenshots found!
      </template>
    </div>
  </div>
</template>

<script>
import axios from "axios";
import Button from "../../../components/Button.vue";
import moment from "moment";
import Input from "../../../components/Input.vue";
import ScreenshotCard from "./screenshots/ScreenshotCard.vue";
import { useUserStore } from "../../../stores/user";

/*
  To-Do:
  - Add confirm dialog for deleting a screenshot
  - Fix clikcing on the card to open bigger screenshot image
*/

export default {
  name: "ScreenshotsTab",
  components: { Button, Input, ScreenshotCard },
  data() {
    return {
      screenshots: [],
      isLoading: true,
      filterType: "Admin",
      filterQuery: "",
      showLimit: 20,
    };
  },
  setup() {
    return {
      api: useUserStore().stats.api,
    };
  },
  computed: {
    filtredScreenshots() {
      return this.filterQuery.replace(/\s/g, "").length > 0
        ? this.screenshots.filter((s) =>
            (this.filterType === "Admin" ? s.admin : s.player)
              .toUpperCase()
              .startsWith(this.filterQuery.replace(/\s/g, "").toUpperCase())
          )
        : this.screenshots;
    },
  },
  methods: {
    toggleTyping(state) {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuToggleTyping", state);
    },
    ssClickHandler(ss) {
      global.Modal.fire({
        imageUrl: `https://phpscreenshotserver.ls-cc.info/screenshots/${ss.name}`,
        width: 1000,
        imageAlt: ss.name,
        confirmButtonText: "Close",
        padding: "1em",
        html: `
        <div class="flex justify-center">
            <div class="flex flex-col items-start">
                <div><strong>Player:</strong> ${ss.player}</div>
                <div><strong>Admin:</strong> ${ss.admin}</div>
                <div><strong>Date:</strong> ${moment(ss.date).format(
                  "MMMM Do YYYY, h:mm:ss A"
                )}</div>
            </div>
        </div>
        `,
      });
    },
    refreshHandler() {
      if (this.isLoading) return;
      this.getScreenshots(true);
    },
    getScreenshots(ann = false) {
      let that = this;
      that.isLoading = true;
      axios
        .get("http://193.70.88.74:8237/ss/list", {
          headers: {
            "x-api-key": this.api,
          },
        })
        .then(function (response) {
          that.screenshots = response.data;
          that.isLoading = false;

          if (ann) global.toast("Screenshot Loaded", null, "success", 5000);
        })
        .catch(function (error) {
          console.log(error);
          that.isLoading = false;
        });
    },
  },
  created() {
    this.getScreenshots();
  },
};
</script>

<style scoped lang="scss">
* {
  color: $white-text;
}

.list-enter-active,
.list-leave-active {
  transition: all 0.4s ease;
}
.list-enter-from,
.list-leave-to {
  opacity: 0;
  transform: translateY(30px);
}

.Screenshots {
  overflow-y: auto;
  height: 720px;
  padding-right: 5px;
  border-radius: $radius-md;
  overflow-x: hidden;
}
</style>
