import { defineStore } from "pinia";
import { v4 as uuidv4 } from "uuid";
import deepClone from "lodash/cloneDeep";

export const useCrosshairStore = defineStore("crosshair", {
  state: () => {
    return {
      // 0 - Toggle, 1 - Slider, 2 - Color
      settingConfig: {
        hidden: {
          label: "Hidden",
          type: -1,
        },
        color: { label: "Color", type: 2 },
        size: {
          label: "Size",
          min: 0,
          max: 20,
          step: 0.1,
          type: 1,
        },
        width: {
          label: "Width",
          min: 0,
          max: 20,
          step: 0.1,
          type: 1,
        },
        rotation: {
          label: "Rotation",
          min: 0,
          max: 360,
          step: 1,
          type: 1,
        },
        gap: {
          label: "Gap",
          min: 0,
          max: 30,
          step: 1,
          type: 1,
        },
        sideTop: {
          label: "Top",
          type: 0,
        },
        sideBottom: {
          label: "Bottom",
          type: 0,
        },
        sideLeft: {
          label: "Left",
          type: 0,
        },
        sideRight: {
          label: "Right",
          type: 0,
        },
        outlineEnabled: {
          label: "Outline",
          type: 0,
        },
        outlineWidth: {
          label: "Outline Width",
          min: 0,
          max: 100,
          step: 1,
          type: 1,
        },
        outlineColor: {
          label: "Outline Color",
          type: 2,
        },
        dotEnabled: {
          label: "Dot",
          type: 0,
        },
        dotColor: {
          label: "Dot Color",
          type: 2,
        },
        dotSize: {
          label: "Dot Size",
          min: 0,
          max: 100,
          step: 1,
          type: 1,
        },
        dotRadius: {
          label: "Dot Radius",
          min: 0,
          max: 100,
          step: 1,
          type: 1,
        },
        offsetTop: {
          label: "Offset Top",
          min: 0,
          max: 100,
          step: 1,
          type: 1,
        },
        offsetRight: {
          label: "Offset Right",
          min: 0,
          max: 100,
          step: 1,
          type: 1,
        },
      },
      layerTypes: [
        {
          type: 0,
          label: "Cross Layer",
          settings: {
            hidden: false,
            color: "#f1f1f1",
            size: 8,
            width: 2,
            rotation: 0,
            gap: 6,

            sideTop: true,
            sideBottom: true,
            sideLeft: true,
            sideRight: true,

            outlineEnabled: false,
            outlineWidth: 1,
            outlineColor: "#f1f1f1",

            dotEnabled: false,
            dotSize: 3,
            dotRadius: 0,
            dotColor: "#f1f1f1",

            offsetTop: 0,
            offsetRight: 0,
          },
        },
      ],
      profiles: [],
      selectedProfile: 1,
    };
  },
  actions: {
    addProfile() {
      let uuid = uuidv4();
      this.profiles.push({
        label: "New Profile",
        uuid: uuid,
        settings: {
          enabled: true,
          alwaysOn: false,
          onSinipers: false,
        },
        layers: [],
      });
      this.selectedProfile = uuid;
    },
    /**
     * Add a layer to the selected profile
     *
     * @param {type} number - 0 - Toggle, 1 - Slider, 2 - Color
     */
    addLayer(type) {
      let newLayer = deepClone(this.layerTypes[type]);
      newLayer.uuid = uuidv4();
      this.getSelectedLayers.push(newLayer);
    },
    cloneLayer(layer) {
      let newLayer = deepClone(layer);
      let uuid = uuidv4();
      newLayer.uuid = uuid;
      this.getSelectedLayers.push(newLayer);
    },
    removeLayer(uuid) {
      let layers = this.getSelectedLayers;
      let index = layers.findIndex((layer) => layer.uuid === uuid);
      this.getSelectedLayers.splice(index, 1);
    },
    cloneProfile(profile) {
      let newProfile = deepClone(profile);
      newProfile.uuid = uuidv4();
      newProfile.layers = newProfile.layers.map((layer) => ({
        ...layer,
        uuid: uuidv4(),
      }));
      this.profiles.push(newProfile);
      this.selectedProfile = newProfile.uuid;
    },
    removeProfile(uuid) {
      if (this.profiles.length < 2) return;
      let index = this.profiles.findIndex((profile) => profile.uuid === uuid);
      this.profiles.splice(index, 1);
      this.selectedProfile = this.profiles[0].uuid;
    },
    setSelectedProfile(uuid) {
      this.selectedProfile = uuid;
    },
  },
  getters: {
    getSelectedLayers() {
      if (this.profiles.length < 1) return [];
      return this.getSelectedProfile.layers;
    },
    getSelectedProfile() {
      return this.profiles.find(
        (profile) => profile.uuid === this.selectedProfile
      );
    },
  },
});
