<template>
  <Card
    class="ScreenshotCard"
    :style="{
      background: `url('${image}') center / cover no-repeat`,
    }"
  >
    <div class="ScreenshotCardInfo">
      <div class="ScreenshotCardTab">
        <i class="fa-duotone fa-user-police"></i> {{ admin }}
      </div>
      <div class="ScreenshotCardTab">
        <i class="fa-duotone fa-user"></i> {{ player }}
      </div>
    </div>
    <Button
      @click="deleteHandler"
      style="position: absolute; bottom: 10px; right: 10px; opacity: 0.8"
      class="gm-button-danger"
      >Delete</Button
    >
  </Card>
</template>

<script>
import Card from "../../../../components/Card.vue";
import Button from "../../../../components/Button.vue";
import axios from "axios";

export default {
  name: "ScreenshotCard",
  components: { Card, Button },
  props: ["fileName", "image", "admin", "player", "getScreenshots", "api"],
  methods: {
    async deleteHandler() {
      axios
        .delete(`http://193.70.88.74:8237/ss/${this.fileName}`, {
          headers: {
            "x-api-key": this.api,
          },
        })
        .then(function (response) {
          console.log(response.data);
          global.toast(
            "Screenshot deleted successfully!",
            null,
            "success",
            5000
          );
        })
        .catch(function (error) {
          console.log(error);
        });
      setTimeout(() => {
        this.getScreenshots();
      }, 500);
    },
  },
};
</script>

<style scoped lang="scss">
.ScreenshotCard {
  height: 250px;
  width: 100%;
  position: relative;
  padding: 0;
  max-width: 400px;

  .ScreenshotCardInfo {
    position: absolute;
    top: 10px;
    color: $white-text;
    display: flex;
    flex-direction: column;
    align-items: flex-start;

    .ScreenshotCardTab {
      background-color: rgba($blue, 0.5);
      backdrop-filter: blur(8.7px);
      border-radius: 0 $radius-md $radius-md 0;
      padding: 10px;
      margin-bottom: 3px;

      i {
        font-size: 1.2em;
      }
    }
  }
}
</style>
