<template>
  <div class="wrap" v-show="enabled">
    <div id="score" class="scoreboard">
      <div id="scoreDrag" class="header">
        <div class="title"><i class="fas fa-gamepad"></i>Players</div>
        <div class="players">{{ players.length }}</div>
      </div>

      <TabsWrapper :wrap="`scoreboardWrap`" ref="selector">
        <Tab title="Global">
          <FilterTab :squad="squadId" :type="1" :players="players" />
        </Tab>
        <Tab title="Lobby">
          <FilterTab
            :squad="squadId"
            :type="2"
            :players="players.filter((p) => p.lid === lobbyId)"
          />
        </Tab>
        <Tab title="Squad">
          <FilterTab
            :squad="squadId"
            :type="3"
            :players="
              squadId >= 0 ? players.filter((p) => p.squad === squadId) : []
            "
          />
        </Tab>
      </TabsWrapper>
    </div>
  </div>
</template>

<script>
import $ from "jquery";
// eslint-disable-next-line no-unused-vars
import draggable from "jquery-ui/ui/widgets/draggable";
import "jquery-ui/themes/base/draggable.css";
import Tab from "../../../../../components/Tab.vue";
import TabsWrapper from "../../../../../components/TabsWrapper.vue";
import FilterTab from "./FilterTab";

export default {
  name: "Scoreboard",
  components: {
    FilterTab,
    Tab,
    TabsWrapper,
  },
  data() {
    return {
      enabled: false,
      squadId: 12,
      lobbyId: 5,
      aplayers: [],
      players: [
        {
          lid: -4,
          squad: -1,
          color: "rgb(0, 151, 255)",
          name: "Kevin",
          level: 1522,
          ping: 152,
        },
        {
          lid: 25,
          squad: 4,
          color: "rgb(0, 151, 255)",
          name: "Kevin2",
          level: 1522,
          ping: 152,
        },
        {
          lid: 42,
          squad: 5,
          color: "rgb(0, 151, 255)",
          name: "Kevin2",
          level: 1522,
          ping: 152,
        },
        {
          lid: 15,
          squad: 8,
          color: "rgb(0, 151, 255)",
          name: "Kevin2",
          level: 1522,
          ping: 152,
        },
        {
          lid: 10,
          squad: 2,
          color: "rgb(0, 151, 255)",
          name: "Kevin2",
          level: 1522,
          ping: 152,
        },
      ],
    };
  },
  mounted() {
    $("#score").draggable({
      handle: "#scoreDrag",
      containment: "body",
    });
  },
  methods: {
    setPlayers(players) {
      this.players = players.sort(function (a, b) {
        return a - b;
      });
    },
  },
};
</script>

