<template>
  <div class="wrap" v-show="enabled">
    <div
      id="actionbar"
      :class="[
        'actionbar actionbar-gauge-container',
        { actionBarFugitive: fugitive },
      ]"
      :key="reActionBar"
    >
      <div class="actionbar-text">{{ this.maxtime - this.time }}s</div>
    </div>
  </div>
</template>

<script>
let Gauge = require("svg-gauge");

export default {
  name: "ActionBar",
  props: ["fugitive"],
  data() {
    return {
      enabled: false,
      debug: false,
      time: 1,
      maxtime: 11,
      bar: null,
      reActionBar: true,
    };
  },
  watch: {
    time(newVal) {
      this.bar.setValueAnimated(newVal);
    },
    maxtime() {
      //force rerender of element
      this.reActionBar = !this.reActionBar;

      //wait a little and set the maxspeed
      setTimeout(() => {
        this.bar = Gauge(document.getElementById("actionbar"), {
          max: this.maxtime,
          dialStartAngle: 90.01,
          dialEndAngle: 89.99,
          dialRadius: 10,
          showValue: false,
          value: this.time,
        });
      }, 50);
    },
  },
  mounted() {
    this.$nextTick(function () {
      this.bar = Gauge(document.getElementById("actionbar"), {
        max: this.maxtime,
        dialStartAngle: 90.01,
        dialEndAngle: 89.99,
        dialRadius: 10,
        showValue: false,
        value: this.time,
      });
    });
  },
};
</script>

<style lang="scss">
.actionBarFugitive.actionbar > .gauge .value-text {
  fill: $orange !important;
}

.actionBarFugitive > .gauge .value {
  stroke: $orange !important;
}

/* ----- Alternate Style ----- */
.actionbar-gauge-container {
  width: 200px;
  height: 200px;
  position: relative;

  .actionbar-text {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 30px;
    font-weight: 500;
    color: #f1f1f1;
  }
}

.actionbar-gauge-container.actionbar > .gauge .dial {
  stroke: rgba(lighten($foreground, 20%), 0.5);
  fill: "#334455";
  stroke-width: 20;
}
.actionbar-gauge-container.actionbar > .gauge .value {
  stroke: $blue;
  stroke-width: 20;
}
.actionbar-gauge-container.actionbar > .gauge .value-text {
  fill: $blue;
  font-size: 0.7em;
}
</style>

<style scoped lang="scss">
.wrap {
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;

  padding-bottom: 100px;
}
</style>
