<template>
  <div class="crosshair-wrap" :style="{ height: h, width: w }">
    <div
      v-for="(layer, index) in crosshair.getSelectedLayers"
      :style="{ zIndex: crosshair.getSelectedLayers.length + 1 - index }"
      :key="layer"
      class="crosshair-inner"
      v-show="!layer.settings.hidden"
    >
      <Cross v-if="layer.type === 0" :settings="layer.settings" />
      <Circle v-else-if="layer.type === 1" :settings="layer.settings" />
    </div>
  </div>
</template>

<script>
import Circle from "./Types/Circle/Circle.vue";
import Cross from "./Types/Cross/Cross.vue";
import { useCrosshairStore } from "../../stores/crosshair";

export default {
  name: "Crosshair",
  components: { Circle, Cross },
  props: ["h", "w"],
  setup() {
    return {
      crosshair: useCrosshairStore(),
    };
  },
};
</script>

<style lang="scss" scoped>
.crosshair-wrap {
  position: relative;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;

  .crosshair-inner {
    position: absolute;
  }
}
</style>
