<template>
  <div class="setting grid">
    <label :id="id">{{ label }}</label>
    <small class="mb-1">{{ description }}</small>
    <Select
      :preSelect="preSelect"
      :options="options"
      :id="`settings${name}`"
      @input="change"
      ref="select"
    />
  </div>
</template>

<script>
import Select from "../../../../components/Select.vue";

export default {
  name: "SelectOption",
  props: ["id", "label", "name", "description", "options", "preSelect"],
  components: {
    Select,
  },
  data() {
    return {};
  },
  methods: {
    change(obj) {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuChangeSettings", this.id, obj.value);
    },
  },
};
</script>

<style scoped lang="scss">
.setting {
  color: $white-text;

  small {
    color: $gray-text;
  }
}
</style>
